(()=>{const form=document.getElementById('retreatForm');if(!form)return;const $=id=>document.getElementById(id),a=$('inquiryArrival'),b=$('inquiryDeparture'),quote=$('retreatQuote'),params=new URLSearchParams(location.search);const today=new Date();today.setHours(12,0,0,0);const stamp=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'),min=stamp(today);a.min=min;b.min=min;const rental=params.get('rental');if(rental&&[...$('selectedRental').options].some(o=>o.value===rental))$('selectedRental').value=rental;if(params.get('arrival')&&params.get('arrival')>=min)a.value=params.get('arrival');if(params.get('departure')&&params.get('departure')>=min)b.value=params.get('departure');a.addEventListener('change',()=>{const d=new Date(a.value+'T12:00:00');if(Number.isFinite(d.getTime())){d.setDate(d.getDate()+2);b.min=stamp(d);if(b.value&&b.value<b.min)b.value=''}});if(a.value)a.dispatchEvent(new Event('change'));if(params.get('guests'))$('adults').value=params.get('guests');
form.addEventListener('submit',e=>{e.preventDefault();const start=new Date(a.value+'T12:00:00'),end=new Date(b.value+'T12:00:00'),nights=Math.round((end-start)/86400000);if(!Number.isFinite(nights)||nights<2){quote.classList.add('visible');quote.replaceChildren();const p=document.createElement('p');p.textContent='Choose a departure at least two nights after arrival.';quote.append(p);quote.scrollIntoView({behavior:'smooth',block:'nearest'});return}const name=$('guestName').value.trim(),rental=$('selectedRental').value,rate=({'The Stillwater Cabin':195,'Fern Hollow':285,'Cedar Observatory':320,'Whispering Pines':225})[rental],extras=[...form.querySelectorAll('[name="addons"]:checked')].map(x=>x.value);quote.classList.add('visible');quote.replaceChildren();const h=document.createElement('strong'),summary=document.createElement('p'),details=document.createElement('p');h.textContent='Your inquiry preview is ready.';summary.textContent=name+', your imagined stay at '+rental+' is '+nights+' nights, with an illustrative subtotal of $'+(rate*nights).toLocaleString('en-US')+' before fees. '+$('adults').value+' adult(s), '+$('children').value+' child(ren).';details.textContent='Contact preference: '+$('contactMethod').value+'. Optional extras: '+(extras.join(', ')||'none')+'. This is a private on-screen preview. No information was sent, stored or booked.';quote.append(h,summary,details);quote.scrollIntoView({behavior:'smooth',block:'nearest'})});
})();
